import{_ as n,C as r,o as i,c as l,j as o,a as p,E as s,ag as a}from"./chunks/framework.D1ek-kcM.js";const q=JSON.parse('{"title":"Requesting an App","description":"","frontmatter":{},"headers":[],"relativePath":"mobile-app/requesting-an-app.md","filePath":"mobile-app/requesting-an-app.md","lastUpdated":1788933864000}'),d={name:"mobile-app/requesting-an-app.md"};function u(h,e,c,g,m,f){const t=r("ImagePopup");return i(),l("div",null,[e[0]||(e[0]=o("h1",{id:"requesting-an-app",tabindex:"-1"},[p("Requesting an App "),o("a",{class:"header-anchor",href:"#requesting-an-app","aria-label":'Permalink to "Requesting an App"'},"​")],-1)),e[1]||(e[1]=o("p",null,"Tenants can ask the platform to build a mobile app for their store. The tenant submits one request with their branding and store account details, and the platform team returns a finished build they can share with their customers.",-1)),s(t,{src:"/images/requesting-an-app/summary.png",alt:"App request process at a glance"}),e[2]||(e[2]=a('<div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What to prepare before starting a request</li><li>How a tenant submits an app request</li><li>What happens after the request is submitted</li></ul></div><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Have these ready. The form cannot be saved as a draft — once submitted it locks, and only fields the super admin flags can be changed afterwards.</p><ul><li><strong>App name</strong> — the name shown under the app icon.</li><li><strong>App logo</strong> — PNG, exactly <strong>512 × 512</strong>.</li><li><strong>Splash image</strong> — PNG, at least <strong>1536 × 2688</strong>. One file, from which every required size is generated.</li><li><strong>Android Application ID</strong> — reverse-domain, such as <code>com.yourbrand.shop</code>. Unique across <strong>every</strong> tenant, and fixed once published.</li><li><strong>iOS Bundle ID</strong> — the same format, such as <code>com.yourbrand.shopios</code>.</li><li><strong>Apple Developer account</strong> — the account type, plus the login credentials.</li><li><strong>Google Play Console account</strong> — the account type, plus the login credentials.</li><li><strong>Firebase project</strong> — the project details.</li></ul><div class="warning custom-block"><p class="custom-block-title">One open request per platform</p><p>A tenant cannot raise a second request covering a platform that already has one open. Wait for the first to be completed or rejected.</p></div><h2 id="step-1-—-open-my-apps" tabindex="-1">Step 1 — Open My Apps <a class="header-anchor" href="#step-1-—-open-my-apps" aria-label="Permalink to &quot;Step 1 — Open My Apps&quot;">​</a></h2><p>Sign in to the tenant admin panel and go to <strong>Mobile App Requests → My Apps</strong>. Every request the tenant has raised is listed here with its current status.</p>',7)),s(t,{src:"/images/requesting-an-app/tenant-my-apps.png",alt:"My Apps list"}),e[3]||(e[3]=a('<p>Select <strong>Request App</strong> in the top right to start a new request.</p><h2 id="step-2-—-fill-in-the-request" tabindex="-1">Step 2 — Fill in the request <a class="header-anchor" href="#step-2-—-fill-in-the-request" aria-label="Permalink to &quot;Step 2 — Fill in the request&quot;">​</a></h2><p>The form is one page. Choosing a platform hides the sections that do not apply — pick <strong>Android &amp; iOS</strong> and everything is shown.</p><ul><li><strong>App Name</strong> — shown under the app icon.</li><li><strong>App Logo</strong> — PNG, exactly 512 × 512. A wrong size is refused at upload.</li><li><strong>App Splash Image</strong> — one PNG, at least 1536 × 2688. The 15 required sizes are generated from it.</li><li><strong>Android Application ID</strong> — for example <code>com.yourbrand.shop</code>.</li><li><strong>iOS Bundle ID</strong> — for example <code>com.yourbrand.shopios</code>.</li><li><strong>Apple Developer Account</strong> — the account type, plus the login credentials.</li><li><strong>Google Play Console Account</strong> — the account type, plus the login credentials.</li><li><strong>Firebase Project</strong> — the project details.</li></ul><p>Each account section carries a one-line hint and a <strong>More info</strong> link to that provider&#39;s documentation.</p><p>Apple and Google Play each ask for an <strong>account type</strong> — Organization or Individual. It tells the mobile team what the account can do before they start, since the two behave differently at release time.</p><div class="warning custom-block"><p class="custom-block-title">Individual accounts</p><p><strong>Google Play</strong> — Individual is accepted, but Google may require a closed test with 12 testers for 14 continuous days before the app can go to production. An Organization account avoids that.</p><p><strong>Apple</strong> — Individual accounts cannot add team members, so the mobile team works from the Apple ID itself rather than being invited to the team.</p></div><p>The grey chips under the splash upload list every size that will be generated from it.</p>',8)),s(t,{src:"/images/requesting-an-app/tenant-request-form.png",alt:"App request form, filled in"}),e[4]||(e[4]=a('<p>Select <strong>Submit Request</strong>.</p><div class="tip custom-block"><p class="custom-block-title">If the form is refused</p><p>Your entries are kept and the reason is shown under the field it belongs to. Two refusals are worth knowing about:</p><ul><li><strong>&quot;This application ID is already in use.&quot;</strong> Application IDs are real store identifiers, so they must be unique across every tenant on the platform — not just your own store. Choose a different one.</li><li><strong>&quot;You already have an open request for this platform.&quot;</strong> See the one-open-request rule above.</li></ul><p>Uploaded images are the one thing that cannot be restored — no browser allows a file input to be refilled — so the logo and splash have to be selected again.</p></div><h2 id="step-3-—-the-request-is-submitted" tabindex="-1">Step 3 — The request is submitted <a class="header-anchor" href="#step-3-—-the-request-is-submitted" aria-label="Permalink to &quot;Step 3 — The request is submitted&quot;">​</a></h2><p>You return to <strong>My Apps</strong> and the request appears as <strong>Pending</strong>. Opening it shows everything that was submitted, including the generated images. Credentials are shown only as <strong>Stored</strong> — for security they cannot be read back, though they can be replaced.</p>',4)),s(t,{src:"/images/requesting-an-app/tenant-request-pending.png",alt:"Submitted request detail"}),e[5]||(e[5]=a('<p>At this point the form is locked. Nothing more is needed from the tenant unless a correction is requested.</p><h2 id="step-4-—-get-the-app" tabindex="-1">Step 4 — Get the app <a class="header-anchor" href="#step-4-—-get-the-app" aria-label="Permalink to &quot;Step 4 — Get the app&quot;">​</a></h2><p>When the build is ready the tenant is e-mailed, and the download links appear on the request under <strong>Your App is Ready</strong>.</p><p>A request for one platform gets one link. A request covering <strong>both</strong> gets two — an <code>.apk</code> or <code>.aab</code> for Android and an App Store link for iOS — each labelled with its platform.</p>',4)),s(t,{src:"/images/requesting-an-app/tenant-download.png",alt:"Download links on the completed request"}),e[6]||(e[6]=a('<p>The tenant shares the links with their customers, and uploads the same build to their own Play Console or App Store Connect account.</p><h2 id="if-a-correction-is-requested" tabindex="-1">If a correction is requested <a class="header-anchor" href="#if-a-correction-is-requested" aria-label="Permalink to &quot;If a correction is requested&quot;">​</a></h2><p>While a request is <strong>Pending</strong>, the super admin can ask for a correction on a single field. The request stays Pending and <strong>only that field reopens</strong> for editing — everything else remains locked. The tenant is e-mailed with the reason, updates that one field, and saves.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><ul><li><strong>Pending</strong> — the request has been submitted and the form is locked.</li><li><strong>Processing</strong> — the platform team has started the build.</li><li><strong>Completed</strong> — the download links are recorded and the tenant has been e-mailed.</li><li><strong>Rejected</strong> — the request was declined, with a reason the tenant can read.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The super admin never sees a tenant&#39;s request until it is submitted, and a tenant never sees another tenant&#39;s requests. Every request is scoped to the store that raised it.</p></div>',6))])}const y=n(d,[["render",u]]);export{q as __pageData,y as default};
